/**
 *
 * DataTableCellEditorDisplay renders the read-only view of an editable cell — shown when the cell
 * is NOT in edit mode. Swaps with DataTableCellEditorContent based on editing state.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableCellEditorDisplay
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
export type DataTableCellEditorDisplayPassThroughType<E> = PassThroughType<DataTableCellEditorDisplayInstance, E>;
export interface DataTableCellEditorDisplayPassThrough {
    root?: DataTableCellEditorDisplayPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
export interface DataTableCellEditorDisplayProps extends BaseComponentProps<DataTableCellEditorDisplayInstance, unknown, DataTableCellEditorDisplayPassThrough, 'div'> {
}
export interface DataTableCellEditorDisplayState {
}
export interface DataTableCellEditorDisplayExposes {
    datatable: DataTableRootInstance | undefined | null;
}
export type DataTableCellEditorDisplayInstance = ComponentInstance<DataTableCellEditorDisplayProps, DataTableCellEditorDisplayState, DataTableCellEditorDisplayExposes>;
